local vvul
do
  local hnxnv, vnfgr = pcall(function() return bit32 end)
  if hnxnv and vnfgr and vnfgr.bxor then
    vvul = function(iqhgg, iepa) return vnfgr.bxor(iqhgg, iepa) % 256 end
  else
    vvul = function(iqhgg, iepa)
      local kcjee, eekt = 0, 1
      while iqhgg > 0 or iepa > 0 do
        local asq, gxd = iqhgg % 2, iepa % 2
        if asq ~= gxd then kcjee = kcjee + eekt end
        iqhgg = (iqhgg - asq) / 2
        iepa = (iepa - gxd) / 2
        eekt = eekt * 2
      end
      return kcjee
    end
  end
end
